const TEXT_COLUMNS = [
  '?????????',
  '??????',
  '????? ??????',
  '??? ?????? ?????? ?? ??????? (ECC Subdomain)',
  '??? ?????? ??????? - ??????',
  '????? ????? ????? ?????',
  '????? ?????? ????? ????? ??? ????? ?????????',
  '????? ?????? ????? ????? ??? ????? ??????',
  '??????',
  '??? ????? ?????? ?? ?????',
  '????? ??????? (??????? ??????)',
  '???????'
];

const CHUNK_SIZE = 1200;
const CHUNK_OVERLAP = 150;

function normalizeArabic(input) {
  if (!input) return '';
  let s = String(input);
  s = s.replace(/[ً-ْ]/g, ''); // diacritics
  s = s.replace(/ـ/g, ''); // tatweel
  s = s.replace(/[???]/g, '?'); // alef
  s = s.replace(/?/g, '?'); // yaa
  s = s.replace(/\s+/g, ' ').trim();
  return s;
}

function detectType(row) {
  if (row['????? ??????']) return 'evidence';
  if (row['??????']) return 'mechanism';
  if (row['?????????']) return 'prerequisite';
  return 'row';
}

function buildDocument(row, index) {
  const parts = [];
  for (const col of TEXT_COLUMNS) {
    const value = row[col];
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      parts.push(normalizeArabic(value));
    }
  }
  const text = parts.join(' | ');
  return {
    text,
    meta: {
      rowIndex: index,
      type: detectType(row),
      eccSubdomain: normalizeArabic(row['??? ?????? ?????? ?? ??????? (ECC Subdomain)'] || ''),
      controlCode: normalizeArabic(row['??? ?????? ??????? - ??????'] || '')
    }
  };
}

function chunkText(text, size, overlap) {
  const chunks = [];
  let start = 0;
  while (start < text.length) {
    const end = Math.min(start + size, text.length);
    const chunk = text.slice(start, end);
    if (chunk.trim().length > 0) chunks.push(chunk);
    if (end === text.length) break;
    start = Math.max(0, end - overlap);
  }
  return chunks;
}

const output = [];
items.forEach((item, idx) => {
  const row = item.json;
  const doc = buildDocument(row, idx);
  if (!doc.text) return;
  const chunks = chunkText(doc.text, CHUNK_SIZE, CHUNK_OVERLAP);
  chunks.forEach((chunk, cidx) => {
    output.push({
      json: {
        text: chunk,
        metadata: { ...doc.meta, chunkIndex: cidx }
      }
    });
  });
});

return output;

// Map OpenAI embeddings output -> json.embedding
const out = [];
for (const item of items) {
  const data = item.json.data || item.json.embedding || [];
  let embedding = [];
  if (Array.isArray(data) && data[0] && data[0].embedding) {
    embedding = data[0].embedding;
  } else if (Array.isArray(item.json.embedding)) {
    embedding = item.json.embedding;
  }
  out.push({ json: { ...item.json, embedding } });
}
return out;
